expr=input().split()
vals=[]
ops=[]
def prec(op):
    return 2 if op=="*" else 1
def apply():
    b=vals.pop()
    a=vals.pop()
    op=ops.pop()
    if op=="+":
        vals.append(a+b)
    elif op=="-":
        vals.append(a-b)
    else:
        vals.append(a*b)
for tk in expr:
    if tk=="(":
        ops.append(tk)
    elif tk==")":
        while ops[-1]!="(":
            apply()
        ops.pop()
    elif tk in ("+","-","*"):
        while ops and ops[-1]!="(" and prec(ops[-1])>=prec(tk):
            apply()
        ops.append(tk)
    else:
        vals.append(int(tk))
while ops:
    apply()
print(vals[0])

