from collections import deque
n,q=map(int,input().split())
g=[[] for _ in range(n+1)]
for _ in range(n-1):
    u,v=map(int,input().split())
    g[u].append(v)
    g[v].append(u)
LOG=1
while (1<<LOG)<n:
    LOG+=1
LOG+=1
up=[[0]*(n+1) for _ in range(LOG)]
depth=[0]*(n+1)
seen=[False]*(n+1)
seen[1]=True
up[0][1]=1
dq=deque([1])
while dq:
    x=dq.popleft()
    for y in g[x]:
        if not seen[y]:
            seen[y]=True
            up[0][y]=x
            depth[y]=depth[x]+1
            dq.append(y)
for k in range(1,LOG):
    for v in range(1,n+1):
        up[k][v]=up[k-1][up[k-1][v]]
def lca(a,b):
    if depth[a]<depth[b]:
        a,b=b,a
    diff=depth[a]-depth[b]
    for k in range(LOG):
        if (diff>>k)&1:
            a=up[k][a]
    if a==b:
        return a
    for k in range(LOG-1,-1,-1):
        if up[k][a]!=up[k][b]:
            a=up[k][a]
            b=up[k][b]
    return up[0][a]
total=0
for _ in range(q):
    a,b=map(int,input().split())
    total+=lca(a,b)
print(total)

