n,q=map(int,input().split())
a=list(map(int,input().split()))
size=1
while size<n:
    size*=2
NEG=-(10**18)
tree=[NEG]*(2*size)
for i in range(n):
    tree[size+i]=a[i]
for i in range(size-1,0,-1):
    tree[i]=max(tree[2*i],tree[2*i+1])
def update(pos,val):
    pos+=size
    tree[pos]=val
    pos//=2
    while pos>=1:
        tree[pos]=max(tree[2*pos],tree[2*pos+1])
        pos//=2
def query(l,r):
    l+=size
    r+=size+1
    res=NEG
    while l<r:
        if l&1:
            res=max(res,tree[l])
            l+=1
        if r&1:
            r-=1
            res=max(res,tree[r])
        l//=2
        r//=2
    return res
total=0
for _ in range(q):
    op=input().split()
    if op[0]=="upd":
        update(int(op[1]),int(op[2]))
    else:
        total+=query(int(op[1]),int(op[2]))
print(total)

