n,q=map(int,input().split())
a=list(map(int,input().split()))
size=1
while size<n:
    size*=2
tree=[0]*(2*size)
lazy=[0]*(2*size)
length=[1]*(2*size)
for i in range(size-1,0,-1):
    length[i]=length[2*i]+length[2*i+1]
for i in range(n):
    tree[size+i]=a[i]
for i in range(size-1,0,-1):
    tree[i]=tree[2*i]+tree[2*i+1]
def push(node):
    if lazy[node]:
        for ch in (2*node,2*node+1):
            lazy[ch]+=lazy[node]
            tree[ch]+=lazy[node]*length[ch]
        lazy[node]=0
def update(node,nl,nr,l,r,x):
    if r<nl or nr<l:
        return
    if l<=nl and nr<=r:
        tree[node]+=x*length[node]
        lazy[node]+=x
        return
    push(node)
    mid=(nl+nr)//2
    update(2*node,nl,mid,l,r,x)
    update(2*node+1,mid+1,nr,l,r,x)
    tree[node]=tree[2*node]+tree[2*node+1]
def query(node,nl,nr,l,r):
    if r<nl or nr<l:
        return 0
    if l<=nl and nr<=r:
        return tree[node]
    push(node)
    mid=(nl+nr)//2
    return query(2*node,nl,mid,l,r)+query(2*node+1,mid+1,nr,l,r)
total=0
for _ in range(q):
    op=input().split()
    if op[0]=="add":
        update(1,0,size-1,int(op[1]),int(op[2]),int(op[3]))
    else:
        total+=query(1,0,size-1,int(op[1]),int(op[2]))
print(total)

