size=1
while size<n:
    size*=2
sm=[0]*(2*size)
lz=[0]*(2*size)
ln=[0]*(2*size)
for i in range(size):
    ln[size+i]=1
for i in range(n):
    sm[size+i]=a[i]
for i in range(size-1,0,-1):
    sm[i]=sm[2*i]+sm[2*i+1]
    ln[i]=ln[2*i]+ln[2*i+1]
def apply(node,v):
    sm[node]+=v*ln[node]
    lz[node]+=v
def push(node):
    if lz[node]!=0:
        apply(2*node,lz[node])
        apply(2*node+1,lz[node])
        lz[node]=0
def add(node,nl,nr,l,r,v):
    if r<nl or nr<l:
        return
    if l<=nl and nr<=r:
        apply(node,v)
        return
    push(node)
    mid=(nl+nr)//2
    add(2*node,nl,mid,l,r,v)
    add(2*node+1,mid+1,nr,l,r,v)
    sm[node]=sm[2*node]+sm[2*node+1]
def qsum(node,nl,nr,l,r):
    if r<nl or nr<l:
        return 0
    if l<=nl and nr<=r:
        return sm[node]
    push(node)
    mid=(nl+nr)//2
    return qsum(2*node,nl,mid,l,r)+qsum(2*node+1,mid+1,nr,l,r)
