for _ in range(q):
    op=input().split()
    if op[0]=="add":
        add(1,0,size-1,int(op[1]),int(op[2]),int(op[3]))
    else:
        total+=qsum(1,0,size-1,int(op[1]),int(op[2]))
print(total)

