n=int(input())
if n==1:
    print(1)
else:
    diag_black=[]
    diag_white=[]
    for d in range(2*n-1):
        cnt=0
        for i in range(n):
            j=d-i
            if 0<=j<n:
                cnt+=1
        if d%2==0:
            diag_black.append(cnt)
        else:
            diag_white.append(cnt)
    def ways(diags):
        diags.sort()
        dp=[1]
        for c in diags:
            ndp=[0]*(len(dp)+1)
            for kk in range(len(dp)):
                if dp[kk]==0:
                    continue
                ndp[kk]+=dp[kk]
                avail=c-kk
                if avail>0:
                    ndp[kk+1]+=dp[kk]*avail
            dp=ndp
        return dp
    wb=ways(diag_black)
    ww=ways(diag_white)
    total=0
    for kk in range(len(wb)):
        if 0<=n-kk<len(ww):
            total+=wb[kk]*ww[n-kk]
    print(total)

