from collections import defaultdict
n=int(input())
pts=[tuple(map(int,input().split())) for _ in range(n)]
if n<=2:
    print(n)
else:
    best=1
    for i in range(n):
        slopes=defaultdict(int)
        for j in range(n):
            if i==j:
                continue
            dx=pts[j][0]-pts[i][0]
            dy=pts[j][1]-pts[i][1]
            g=math.gcd(abs(dx),abs(dy))
            if g!=0:
                dx//=g
                dy//=g
            if dx<0 or (dx==0 and dy<0):
                dx=-dx
                dy=-dy
            slopes[(dx,dy)]+=1
        for v in slopes.values():
            if v+1>best:
                best=v+1
    print(best)

