n=int(input())
pts=[tuple(map(int,input().split())) for _ in range(n)]
if n<3:
    print("yes")
else:
    sign=0
    ok=True
    for i in range(n):
        ax,ay=pts[i]
        bx,by=pts[(i+1)%n]
        cx,cy=pts[(i+2)%n]
        cross=(bx-ax)*(cy-by)-(by-ay)*(cx-bx)
        if cross!=0:
            s=1 if cross>0 else -1
            if sign==0:
                sign=s
            elif s!=sign:
                ok=False
                break
    print("yes" if ok else "no")

